  --gray-100: #F5F6F8;
  --gray-200: #E8EAED;
  --gray-300: #D1D5DB;
  --gray-500: #6B7280;
  --gray-700: #374151;
  --text-dark: #1F2937;
  --text-body: #4B5563;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-dark);
  background: var(--white);
}

h1, h2, h3, h4, h5 {
  font-weight: 600;
  line-height: 1.2;
  color: var(--navy);
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }

/* Typography Scale */
h1 { font-size: clamp(2rem, 4vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 3vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2vw, 1.75rem); }
h4 { font-size: 1.25rem; }

/* Container */
.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 2rem;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 1.75rem;
  font-size: 0.9375rem;
  font-weight: 500;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s;
  border: none;
}

.btn-primary {
  background: var(--teal);
  color: var(--white);
}
.btn-primary:hover { background: var(--teal-light); }

.btn-secondary {
  background: transparent;
  color: var(--navy);
  border: 1px solid var(--navy);
}
.btn-secondary:hover { background: var(--navy); color: var(--white); }

.btn-gold {
  background: var(--gold);
  color: var(--navy);
}
.btn-gold:hover { background: #D4B46A; }

.btn-text {
  background: none;
  color: var(--teal);
  padding: 0;
  font-weight: 600;
}
.btn-text:hover { color: var(--teal-light); }
.btn-text::after { content: ' →'; }

/* Header */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: var(--navy);
  transition: box-shadow 0.3s;
}

.header.scrolled { box-shadow: 0 2px 20px rgba(0,0,0,0.15); }

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 2rem;
  max-width: 1440px;
  margin: 0 auto;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--white);
  font-size: 1.5rem;
  font-weight: 700;
}

.logo svg { width: 40px; height: 40px; }

/* Nav */
.nav-main { display: flex; align-items: center; gap: 2rem; }

.nav-link {
  color: rgba(255,255,255,0.85);
  font-size: 0.9375rem;
  font-weight: 500;
  padding: 0.5rem 0;
  position: relative;
  transition: color 0.2s;
}

.nav-link:hover, .nav-link.active { color: var(--white); }

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--teal);
  transition: width 0.3s;
}

.nav-link:hover::after, .nav-link.active::after { width: 100%; }

/* Mega Menu */
.nav-item-has-mega { position: relative; }

.mega-trigger {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  color: rgba(255,255,255,0.85);
  font-size: 0.9375rem;
  font-weight: 500;
  padding: 0.5rem 0;
  background: none;
  border: none;
  cursor: pointer;
}

.mega-trigger:hover, .mega-trigger.active { color: var(--white); }
.mega-trigger svg { width: 12px; height: 12px; transition: transform 0.2s; }
.mega-trigger.active svg { transform: rotate(180deg); }

.mega-menu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  background: var(--white);
  border-radius: 8px;
  box-shadow: 0 20px 60px rgba(0,0,0,0.25);
  padding: 2rem;
  min-width: 600px;
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s;
}

.nav-item-has-mega:hover .mega-menu,
.mega-trigger.active + .mega-menu {
  opacity: 1;
  visibility: visible;
}

.mega-menu-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}

.mega-col h4 {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-500);
  margin-bottom: 0.75rem;
}

.mega-col ul { list-style: none; }

.mega-col li { margin-bottom: 0.5rem; }

.mega-col a {
  color: var(--navy);
  font-size: 0.9375rem;
  display: block;
  padding: 0.375rem 0;
  transition: color 0.2s;
}

.mega-col a:hover { color: var(--teal); }

/* Mobile Nav Toggle */
.nav-mobile-toggle {
  display: none;
  background: none;
  border: none;
  color: var(--white);
  cursor: pointer;
  padding: 0.5rem;
}

.nav-mobile-toggle svg { width: 24px; height: 24px; }

/* Mobile Menu */
.mobile-menu {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--navy);
  z-index: 999;
  overflow-y: auto;
}

.mobile-menu.active { display: block; }

.mobile-menu-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem 2rem;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.mobile-menu-close {
  background: none;
  border: none;
  color: var(--white);
  cursor: pointer;
}

.mobile-nav { padding: 1rem 2rem; }

.mobile-nav-section { border-bottom: 1px solid rgba(255,255,255,0.1); }

.mobile-nav-section > button {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  background: none;
  border: none;
  color: var(--white);
  font-size: 1rem;
  font-weight: 500;
  padding: 1rem 0;
  cursor: pointer;
  text-align: left;
}

.mobile-nav-section > button svg { width: 20px; height: 20px; transition: transform 0.2s; }
.mobile-nav-section.active > button svg { transform: rotate(180deg); }

.mobile-subnav {
  display: none;
  padding: 0.5rem 0 1rem 1rem;
}

.mobile-nav-section.active .mobile-subnav { display: block; }

.mobile-subnav a {
  display: block;
  color: rgba(255,255,255,0.7);
  font-size: 0.9375rem;
  padding: 0.5rem 0;
}

.mobile-subnav a:hover { color: var(--white); }

/* Hero */
.hero {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-light) 100%);
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background-image: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1440 900"><rect fill="%230A1628" width="1440" height="900"/><g fill-opacity="0.15"><path d="M0 600h1440v-100L0 500zM0 800h1440v-150L0 650z"/></g></svg>');
  background-size: cover;
  background-position: center;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, rgba(10,22,40,0.95) 0%, rgba(10,22,40,0.7) 100%);
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 700px;
}

.hero-tag {
  display: inline-block;
  background: rgba(255,255,255,0.1);
  color: var(--gold);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  padding: 0.5rem 1rem;
  border-radius: 2px;
  margin-bottom: 1.5rem;
}

.hero h1 {
  color: var(--white);
  margin-bottom: 1.5rem;
}

.hero-subtitle {
  color: rgba(255,255,255,0.8);
  font-size: 1.25rem;
  margin-bottom: 2rem;
  line-height: 1.5;
}

/* Page Hero (inner pages) */
.page-hero {
  padding: 160px 0 100px;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-light) 100%);
  position: relative;
  overflow: hidden;
}

.page-hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><defs><pattern id="grid" width="10" height="10" patternUnits="userSpaceOnUse"><path d="M 10 0 L 0 0 0 10" fill="none" stroke="rgba(255,255,255,0.03)" stroke-width="0.5"/></pattern></defs><rect fill="url(%23grid)" width="100" height="100"/></svg>');
}

.page-hero-content { position: relative; z-index: 1; }

.page-hero h1 {
  color: var(--white);
  margin-bottom: 1rem;
}

.page-hero-subtitle {
  color: rgba(255,255,255,0.8);
  font-size: 1.25rem;
  max-width: 600px;
}

/* Sections */
.section { padding: 80px 0; }
.section-dark { background: var(--navy); color: var(--white); }
.section-light { background: var(--gray-100); }

.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 3rem;
}

.section-header h2 { margin-bottom: 1rem; }
.section-header p { color: var(--text-body); font-size: 1.125rem; }

.section-header.light h2 { color: var(--white); }
.section-header.light p { color: rgba(255,255,255,0.7); }

/* Announcement Banner */
.announcement {
  background: var(--teal);
  padding: 0.875rem 0;
  text-align: center;
}

.announcement p {
  color: var(--white);
  font-size: 0.9375rem;
  font-weight: 500;
}

.announcement a {
  text-decoration: underline;
  margin-left: 0.5rem;
}

/* Featured Insights (Home) */
.insights-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
}

.insight-card {
  background: var(--white);
  border-radius: 8px;
  overflow: hidden;
  box-shadow: 0 4px 20px rgba(0,0,0,0.08);
  transition: transform 0.3s, box-shadow 0.3s;
}

.insight-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 30px rgba(0,0,0,0.12);
}

.insight-card-image {
  height: 180px;
  background: linear-gradient(135deg, var(--navy-light) 0%, var(--navy) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.3);
  font-size: 3rem;
}

.insight-card-body { padding: 1.5rem; }

.insight-tag {
  display: inline-block;
  background: var(--gray-100);
  color: var(--text-body);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 0.25rem 0.75rem;
  border-radius: 2px;
  margin-bottom: 0.75rem;
}

.insight-card h3 {
  font-size: 1.125rem;
  margin-bottom: 0.75rem;
  line-height: 1.4;
}

.insight-card p {
  color: var(--text-body);
  font-size: 0.9375rem;
  margin-bottom: 1rem;
}

.insight-card .date {
  color: var(--gray-500);
  font-size: 0.8125rem;
}

/* About Statement */
.about-statement {
  background: var(--white);
  text-align: center;
  padding: 100px 0;
}

.about-statement p {
  font-size: 1.5rem;
  line-height: 1.6;
  color: var(--text-dark);
  max-width: 900px;
  margin: 0 auto 2rem;
}

/* What We Do Tabs */
.what-we-do { background: var(--gray-100); }

.tabs-container {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 0;
  background: var(--white);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 4px 30px rgba(0,0,0,0.08);
}

.tabs-list {
  background: var(--navy);
  padding: 2rem 0;
}

.tab-btn {
  display: block;
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  color: rgba(255,255,255,0.7);
  font-size: 1rem;
  font-weight: 500;
  padding: 1rem 2rem;
  cursor: pointer;
  transition: all 0.2s;
  border-left: 3px solid transparent;
}

.tab-btn:hover { color: var(--white); background: rgba(255,255,255,0.05); }

.tab-btn.active {
  color: var(--white);
  background: rgba(255,255,255,0.1);
  border-left-color: var(--gold);
}

.tab-content {
  padding: 3rem;
  display: none;
}

.tab-content.active { display: block; }

.tab-content h3 {
  font-size: 1.75rem;
  margin-bottom: 1rem;
}

.tab-content p {
  color: var(--text-body);
  font-size: 1.0625rem;
  line-height: 1.7;
  margin-bottom: 1.5rem;
}

/* Newsletter */
.newsletter {
  background: var(--navy);
  padding: 80px 0;
  text-align: center;
}

.newsletter h2 { color: var(--white); margin-bottom: 0.75rem; }
.newsletter p { color: rgba(255,255,255,0.7); margin-bottom: 2rem; }

.newsletter-form {
  display: flex;
  gap: 1rem;
  max-width: 500px;
  margin: 0 auto;
}

.newsletter-form input {
  flex: 1;
  padding: 0.875rem 1rem;
  border: none;
  border-radius: 4px;
  font-size: 1rem;
}

.newsletter-form button { white-space: nowrap; }

/* Our Commitment */
.commitment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.commitment-card {
  background: var(--white);
  padding: 2rem;
  border-radius: 8px;
  border: 1px solid var(--gray-200);
  transition: border-color 0.2s, box-shadow 0.2s;
}

.commitment-card:hover {
  border-color: var(--teal);
  box-shadow: 0 4px 20px rgba(0,0,0,0.08);
}

.commitment-card-icon {
  width: 48px;
  height: 48px;
  background: var(--gray-100);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: var(--navy);
}

.commitment-card h4 { margin-bottom: 0.75rem; }
.commitment-card p { color: var(--text-body); font-size: 0.9375rem; margin-bottom: 1rem; }

/* Footer */
.footer {
  background: var(--navy);
  color: rgba(255,255,255,0.8);
  padding: 60px 0 30px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 3rem;
  margin-bottom: 3rem;
}

.footer-brand p {
  font-size: 0.9375rem;
  line-height: 1.7;
  margin: 1rem 0 1.5rem;
  max-width: 300px;
}

.footer h5 {
  color: var(--white);
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 1.25rem;
}

.footer ul { list-style: none; }

.footer li { margin-bottom: 0.75rem; }

.footer a {
  color: rgba(255,255,255,0.7);
  font-size: 0.9375rem;
  transition: color 0.2s;
}

.footer a:hover { color: var(--white); }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 2rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.875rem;
}

.footer-legal { display: flex; gap: 2rem; }

.footer-legal a {
  color: rgba(255,255,255,0.5);
  font-size: 0.8125rem;
}

.footer-legal a:hover { color: rgba(255,255,255,0.8); }

/* Service Categories (Services Page) */
.service-categories {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.service-category-card {
  background: var(--white);
  border-radius: 12px;
  padding: 2.5rem;
  border: 1px solid var(--gray-200);
  transition: all 0.3s;
}

.service-category-card:hover {
  border-color: var(--teal);
  box-shadow: 0 8px 40px rgba(0,0,0,0.1);
}

.service-category-card h3 { margin-bottom: 1rem; }
.service-category-card p { color: var(--text-body); margin-bottom: 1.5rem; }

/* Capabilities Grid (Detail Pages) */
.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.capability-card {
  background: var(--white);
  border-radius: 12px;
  padding: 2rem;
  border: 1px solid var(--gray-200);
  transition: all 0.3s;
}

.capability-card:hover {
  border-color: var(--teal);
  box-shadow: 0 8px 40px rgba(0,0,0,0.1);
}

.capability-card h4 { margin-bottom: 0.75rem; }
.capability-card p { color: var(--text-body); font-size: 0.9375rem; margin-bottom: 1.25rem; }

/* Partners Carousel */
.partners-section { background: var(--gray-100); }

.partners-carousel {
  display: flex;
  gap: 2rem;
  overflow-x: auto;
  padding: 1rem 0;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
}

.partners-carousel::-webkit-scrollbar { display: none; }

.partner-card {
  flex: 0 0 300px;
  background: var(--white);
  border-radius: 12px;
  padding: 2rem;
  scroll-snap-align: start;
  box-shadow: 0 4px 20px rgba(0,0,0,0.06);
}

.partner-logo {
  height: 60px;
  background: var(--navy);
  border-radius: 8px;
  margin-bottom: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(255,255,255,0.5);
  font-weight: 600;
}

.partner-card h4 { margin-bottom: 0.5rem; }
.partner-card p { color: var(--text-body); font-size: 0.9375rem; }

/* Testimonial */
.testimonial {
  background: var(--navy);
  padding: 80px 0;
  text-align: center;
}

.testimonial blockquote {
  font-size: 1.75rem;
  color: var(--white);
  line-height: 1.5;
  max-width: 900px;
  margin: 0 auto 2rem;
  font-style: italic;
}

.testimonial cite {
  color: var(--gold);
  font-style: normal;
  font-size: 1rem;
  font-weight: 500;
}

/* CTA Sections */
.cta-section {
  padding: 80px 0;
  text-align: center;
}

.cta-section h2 { margin-bottom: 1rem; }
.cta-section p { color: var(--text-body); margin-bottom: 2rem; max-width: 600px; margin-left: auto; margin-right: auto; }

/* Featured Topics */
.featured-topics {
  background: var(--gray-100);
}

.topics-sidebar {
  background: var(--white);
  border-radius: 12px;
  padding: 2rem;
  border: 1px solid var(--gray-200);
}

.topics-sidebar h4 {
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--gray-500);
  margin-bottom: 1.5rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--gray-200);
}

.topics-sidebar ul { list-style: none; }

.topics-sidebar li {
  margin-bottom: 1rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--gray-200);
}

.topics-sidebar li:last-child { border-bottom: none; margin-bottom: 0; padding-bottom: 0; }

.topics-sidebar a {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  color: var(--navy);
  font-weight: 500;
  transition: color 0.2s;
}

.topics-sidebar a:hover { color: var(--teal); }

/* Grid Layout Helpers */
.grid-2-col { display: grid; grid-template-columns: 2fr 1fr; gap: 3rem; }

/* Responsive */
@media (max-width: 1024px) {
  .tabs-container { grid-template-columns: 1fr; }
  .tabs-list { display: flex; overflow-x: auto; padding: 0; }
  .tab-btn { padding: 1rem 1.5rem; white-space: nowrap; border-left: none; border-bottom: 3px solid transparent; }
  .tab-btn.active { border-bottom-color: var(--gold); }
  .commitment-grid { grid-template-columns: repeat(2, 1fr); }
  .service-categories { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .capabilities-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .nav-main { display: none; }
  .nav-mobile-toggle { display: block; }
  .mega-menu { display: none; }
  .hero { min-height: 70vh; }
  .section { padding: 60px 0; }
  .newsletter-form { flex-direction: column; }
  .commitment-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 1rem; }
  .service-categories { grid-template-columns: 1fr; }
  .capabilities-grid { grid-template-columns: 1fr; }
  .grid-2-col { grid-template-columns: 1fr; }
  .page-hero { padding: 120px 0 60px; }
